<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/decks/combo-creator.php';
$pdo=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
